/// Public key for entitlement tokens generated by the local admin tool.
pub const CHANNEL_ENTITLEMENT_PUBLIC_KEY: [u8; 32] = [
    0xa1, 0x6a, 0x5b, 0x23, 0xc7, 0x82, 0xb0, 0xae,
    0x9c, 0x7b, 0xe5, 0x8f, 0xf6, 0xbe, 0xe0, 0x1e,
    0x99, 0x78, 0xd5, 0x4f, 0xdc, 0x18, 0x26, 0x62,
    0x5f, 0x7a, 0xd7, 0x9c, 0x8f, 0x66, 0xc8, 0xaf,
];

