impl EventDocument {
    /// Crea un nuevo documento de evento
    pub fn new(
        peer_id: String,
        revision: u64,
        nickname: String,
        event: EventData,
        schedule: Schedule,
        flyer: Option<FlyerData>,
        channel: String,
        id: Option<String>,
    ) -> Self {
        let now = chrono::Utc::now();
        let now_rfc3339 = now.to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        let author_id = otes_author_id(&peer_id).unwrap_or_else(|_| peer_id.clone());
        let mut event = event;
        if event.language.is_empty() {
            event.language = "es".to_string();
        }
        if event.network.server.is_empty() {
            event.network.server = event.server.clone();
        }
        if event.network.name.is_empty() {
            event.network.name = event.network.server.clone();
        }
        if event.links.is_empty() && !event.link.is_empty() {
            event.links.push(Link {
                rel: "details".to_string(),
                url: event.link.clone(),
                label: String::new(),
            });
        }
        if event.route.is_none() {
            let mut route = Route::default();
            if !event.route.as_ref().is_some_and(|r| !r.origins.is_empty()) && !event.server.is_empty() {
                route.origins.push(Place {
                    city: event.server.clone(),
                    location: String::new(),
                    country: String::new(),
                });
            }
            event.route = Some(route);
        }
        event.schedule = schedule;
        let meeting_timestamp = event.schedule.meeting_timestamp;
        event.schedule.start_timestamp.get_or_insert(meeting_timestamp);

        Self {
            schema: SCHEMA_EVENT.to_string(),
            spec_version: CTES_VERSION.to_string(),
            kind: "event".to_string(),
            id: id.unwrap_or_else(|| uuid::Uuid::now_v7().to_string()),
            revision,
            author_id,
            created_at: now_rfc3339.clone(),
            updated_at: now_rfc3339,
            event,
            signature: String::new(),
            peer_id,
            nickname,
            published_at: chrono::Utc::now().timestamp(),
            channel,
            flyer,
            delete_signature: String::new(),
            deleted: false,
        }
    }

    /// Serialización canónica para firma (claves ordenadas, sin el campo signature)
    pub fn canonical_json(&self) -> Result<String> {
        // Crear copia sin signature
        let mut copy = self.clone();
        copy.signature = String::new();
        copy.delete_signature = String::new();
        copy.deleted = false;
        if copy.event.network.server.is_empty() {
            copy.event.network.server = copy.event.server.clone();
        }
        if copy.event.network.name.is_empty() {
            copy.event.network.name = copy.event.network.server.clone();
        }
        if copy.event.links.is_empty() && !copy.event.link.is_empty() {
            copy.event.links.push(Link {
                rel: "details".to_string(),
                url: copy.event.link.clone(),
                label: String::new(),
            });
        }
        if copy.event.route.is_none() {
            let mut route = Route::default();
            if !copy.event.server.is_empty() {
                route.origins.push(Place {
                    city: copy.event.server.clone(),
                    location: String::new(),
                    country: String::new(),
                });
            }
            copy.event.route = Some(route);
        }
        let meeting_timestamp = copy.event.schedule.meeting_timestamp;
        copy.event.schedule.start_timestamp.get_or_insert(meeting_timestamp);
        if copy.created_at.is_empty() {
            copy.created_at = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        }
        if copy.updated_at.is_empty() {
            copy.updated_at = copy.created_at.clone();
        }
        if copy.revision == 1 {
            copy.revision = 0;
        }

        // Serializar con claves ordenadas
        let value = serde_json::to_value(&copy)
            .context("Failed to serialize EventDocument for canonical JSON")?;
        let mut value = value;
        if let Some(obj) = value.as_object_mut() {
            if obj.get("revision").and_then(|v| v.as_u64()) == Some(0) {
                obj.remove("revision");
            }
        }
        Ok(canonical_json(&value))
    }

    /// Firma el registro con la clave secreta
    pub fn sign(&mut self, secret_key: &SecretKey) -> Result<()> {
        use ed25519_dalek::{Signer, SigningKey};

        let canonical = self.canonical_json()?;
        let message = canonical.as_bytes();

        // Convertir SecretKey de iroh a SigningKey de ed25519-dalek
        let key_bytes = secret_key.to_bytes();
        let signing_key = SigningKey::from_bytes(&key_bytes);

        let signature = signing_key.sign(message);
        self.signature = base64::Engine::encode(
            &base64::engine::general_purpose::STANDARD,
            signature.to_bytes(),
        );

        Ok(())
    }

    /// Verifica la firma del registro
    pub fn verify(&self) -> Result<bool> {
        use ed25519_dalek::{Verifier, VerifyingKey};

        if self.signature.is_empty() {
            return Ok(false);
        }

        // Decodificar peer_id a public key (soporta hex y base64)
        let signer_id = if self.author_id.is_empty() {
            &self.peer_id
        } else {
            &self.author_id
        };
        let key_array = match decode_peer_id_bytes(signer_id) {
            Ok(k) => k,
            Err(_) => return Ok(false),
        };
        let verifying_key = VerifyingKey::from_bytes(&key_array).context("Invalid public key")?;

        // Decodificar firma
        let sig_bytes = base64::Engine::decode(
            &base64::engine::general_purpose::STANDARD,
            &self.signature,
        )
        .context("Failed to decode signature")?;

        if sig_bytes.len() != 64 {
            return Ok(false);
        }

        let mut sig_array = [0u8; 64];
        sig_array.copy_from_slice(&sig_bytes);
        let signature = ed25519_dalek::Signature::from_bytes(&sig_array);

        // Verificar
        let canonical = self.canonical_json()?;
        let message = canonical.as_bytes();

        Ok(verifying_key.verify(message, &signature).is_ok())
    }

    pub fn wins_over(&self, existing: &Self) -> bool {
        if self.author_id != existing.author_id {
            return false;
        }
        if self.revision != existing.revision {
            return self.revision > existing.revision;
        }
        if self.deleted != existing.deleted {
            return self.deleted;
        }
        self.signature > existing.signature
    }

    /// Verifica si el convoy aún es válido (no expiró)
    pub fn is_retained(&self, now: i64) -> bool {
        const RETENTION_DAYS: i64 = 3;
        self.event.schedule.meeting_timestamp + RETENTION_DAYS * 86400 > now
    }

    /// Verifica si el convoy se puede publicar (dentro del horizonte)
    pub fn is_within_publish_window(&self, now: i64) -> bool {
        const PUBLISH_HORIZON_DAYS: i64 = 90;
        self.event.schedule.meeting_timestamp <= now + PUBLISH_HORIZON_DAYS * 86400
    }
}

impl VoteRecord {
    pub fn new(event_id: String, author_id: String, value: i32, previous: Option<&Self>) -> Self {
        let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        Self {
            spec_version: CTES_VERSION.to_string(),
            kind: "vote".to_string(),
            event_id,
            revision: previous.map_or(1, |vote| vote.revision.saturating_add(1)),
            author_id,
            created_at: previous.map_or_else(|| now.clone(), |vote| vote.created_at.clone()),
            updated_at: now,
            data: VoteData { value },
            signature: String::new(),
        }
    }

    /// Serialización canónica para firma
    pub fn canonical_json(&self) -> Result<String> {
        let mut value = serde_json::to_value(self)
            .context("Failed to serialize VoteRecord for canonical JSON")?;
        value.as_object_mut().context("VoteRecord must be an object")?.remove("signature");
        Ok(canonical_json(&value))
    }

    /// Firma el voto
    pub fn sign(&mut self, secret_key: &SecretKey) -> Result<()> {
        use ed25519_dalek::{Signer, SigningKey};

        let canonical = self.canonical_json()?;
        let message = canonical.as_bytes();

        let key_bytes = secret_key.to_bytes();
        let signing_key = SigningKey::from_bytes(&key_bytes);

        let signature = signing_key.sign(message);
        self.signature = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            signature.to_bytes(),
        );

        Ok(())
    }

    /// Verifica la firma del voto
    pub fn verify(&self) -> Result<bool> {
        use ed25519_dalek::{Verifier, VerifyingKey};

        if self.signature.is_empty() {
            return Ok(false);
        }

        let key_array = match decode_peer_id_bytes(&self.author_id) {
            Ok(k) => k,
            Err(_) => return Ok(false),
        };
        let verifying_key = VerifyingKey::from_bytes(&key_array).context("Invalid public key")?;

        let sig_bytes = base64::Engine::decode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            &self.signature,
        )
        .context("Failed to decode signature")?;

        if sig_bytes.len() != 64 {
            return Ok(false);
        }

        let mut sig_array = [0u8; 64];
        sig_array.copy_from_slice(&sig_bytes);
        let signature = ed25519_dalek::Signature::from_bytes(&sig_array);

        let canonical = self.canonical_json()?;
        let message = canonical.as_bytes();

        Ok(verifying_key.verify(message, &signature).is_ok())
    }

    pub fn validate(&self) -> bool {
        let event_id = uuid::Uuid::parse_str(&self.event_id);
        let created = chrono::DateTime::parse_from_rfc3339(&self.created_at);
        let updated = chrono::DateTime::parse_from_rfc3339(&self.updated_at);
        self.spec_version == CTES_VERSION
            && self.kind == "vote"
            && (1..=9_007_199_254_740_991).contains(&self.revision)
            && event_id.is_ok_and(|id| id.get_version_num() == 7)
            && self.author_id.starts_with("ed25519:")
            && self.author_id.len() == 51
            && decode_peer_id_bytes(&self.author_id).is_ok()
            && matches!(self.data.value, -1..=1)
            && self.created_at.ends_with('Z')
            && self.updated_at.ends_with('Z')
            && created.is_ok()
            && updated.is_ok()
            && created.unwrap() <= updated.unwrap()
    }

    pub fn wins_over(&self, existing: &Self) -> bool {
        if self.revision != existing.revision {
            return self.revision > existing.revision;
        }
        self.signature > existing.signature
    }
}

impl ProfileRecord {
    pub fn new(author_id: String, nickname: String, previous: Option<&Self>) -> Self {
        let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        Self {
            spec_version: CTES_VERSION.to_string(),
            kind: "profile".to_string(),
            revision: previous.map_or(1, |profile| profile.revision.saturating_add(1)),
            author_id,
            created_at: previous.map_or_else(|| now.clone(), |profile| profile.created_at.clone()),
            updated_at: now,
            data: ProfileData { nickname, links: Vec::new() },
            signature: String::new(),
        }
    }

    pub fn canonical_json(&self) -> Result<String> {
        let mut value = serde_json::to_value(self).context("Failed to serialize CTES profile")?;
        value.as_object_mut().context("ProfileRecord must be an object")?.remove("signature");
        Ok(canonical_json(&value))
    }

    pub fn sign(&mut self, secret_key: &SecretKey) -> Result<()> {
        use ed25519_dalek::{Signer, SigningKey};
        let signing_key = SigningKey::from_bytes(&secret_key.to_bytes());
        let signature = signing_key.sign(self.canonical_json()?.as_bytes());
        self.signature = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            signature.to_bytes(),
        );
        Ok(())
    }

    pub fn verify(&self) -> Result<bool> {
        use ed25519_dalek::{Verifier, VerifyingKey};
        if !self.validate() {
            return Ok(false);
        }
        let verifying_key = VerifyingKey::from_bytes(&decode_peer_id_bytes(&self.author_id)?)?;
        let bytes = base64::Engine::decode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            &self.signature,
        )?;
        let signature: [u8; 64] = bytes.try_into().map_err(|_| anyhow::anyhow!("Invalid signature length"))?;
        Ok(verifying_key.verify(
            self.canonical_json()?.as_bytes(),
            &ed25519_dalek::Signature::from_bytes(&signature),
        ).is_ok())
    }

    pub fn validate(&self) -> bool {
        let created = chrono::DateTime::parse_from_rfc3339(&self.created_at);
        let updated = chrono::DateTime::parse_from_rfc3339(&self.updated_at);
        self.spec_version == CTES_VERSION
            && self.kind == "profile"
            && (1..=9_007_199_254_740_991).contains(&self.revision)
            && self.author_id.len() == 51
            && decode_peer_id_bytes(&self.author_id).is_ok()
            && !self.data.nickname.trim().is_empty()
            && self.data.nickname.chars().count() <= 32
            && self.data.links.len() <= 10
            && self.created_at.ends_with('Z')
            && self.updated_at.ends_with('Z')
            && created.is_ok() && updated.is_ok()
            && created.unwrap() <= updated.unwrap()
    }

    pub fn wins_over(&self, existing: &Self) -> bool {
        self.revision > existing.revision
            || (self.revision == existing.revision && self.signature > existing.signature)
    }
}

impl ChannelRecord {
    /// Verifica si este canal es del sistema (sin owner)
    pub fn is_system(&self) -> bool {
        self.creator_peer_id == SYSTEM_PEER_ID
    }

    /// Verifica si el peer ID dado es el dueño de este canal
    pub fn is_owner(&self, peer_id: &str) -> bool {
        if self.is_system() {
            return false; // Los canales del sistema no tienen dueño
        }
        self.creator_peer_id == peer_id
    }

    /// Verifica si un peer puede publicar por grant
    pub fn is_authorized(&self, peer_id: &str) -> bool {
        self.authorized_peer_ids.iter().any(|authorized| authorized == peer_id)
    }

    /// Agrega un peer autorizado si no existe
    pub fn add_authorized_peer(&mut self, peer_id: String) -> bool {
        if self.authorized_peer_ids.iter().any(|existing| existing == &peer_id) {
            return false;
        }
        self.authorized_peer_ids.push(peer_id);
        true
    }

    /// Quita un peer autorizado si existe
    pub fn remove_authorized_peer(&mut self, peer_id: &str) -> bool {
        let before = self.authorized_peer_ids.len();
        self.authorized_peer_ids.retain(|existing| existing != peer_id);
        before != self.authorized_peer_ids.len()
    }
}

impl ConvoyStore {
    /// Carga el store desde disco
    pub fn load(data_dir: &Path) -> Result<Self> {
        let store_path = data_dir.join("convoy_store.json");
        if store_path.exists() {
            let store_str = std::fs::read_to_string(&store_path)
                .context("Failed to read convoy store")?;
            let store: Self = match serde_json::from_str(&store_str) {
                Ok(store) => store,
                Err(err) => {
                    eprintln!("[P2P] Failed to parse convoy store: {}", err);
                    quarantine_corrupt_file(&store_path, "convoy_store");
                    return Ok(Self::default());
                }
            };
            Ok(Self {
                convoys: store
                    .convoys
                    .into_iter()
                    .map(|(id, event)| (id, normalize_loaded_event_document(event)))
                    .collect(),
                votes: store.votes,
                profiles: store.profiles,
            })
        } else {
            Ok(Self::default())
        }
    }

    /// Guarda el store a disco (write atómico: temp file + rename)
    pub fn save(&self, data_dir: &Path) -> Result<()> {
        let store_path = data_dir.join("convoy_store.json");
        let tmp_path = data_dir.join("convoy_store.json.tmp");
        std::fs::write(&tmp_path, serde_json::to_string(self)?)
            .context("Failed to write convoy store")?;
        replace_file(&tmp_path, &store_path).context("Failed to rename convoy store")?;
        Ok(())
    }

    /// Agrega o actualiza un convoy
    pub fn upsert_convoy(&mut self, convoy: EventDocument) {
        let convoy = normalize_loaded_event_document(convoy);
        if let Some(existing) = self.convoys.get(&convoy.id) {
            if !convoy.wins_over(existing) {
                return;
            }
        }
        self.convoys.insert(convoy.id.clone(), convoy);
    }

    pub fn upsert_vote(&mut self, vote: VoteRecord) -> bool {
        let event_votes = self.votes.entry(vote.event_id.clone()).or_default();
        if event_votes.get(&vote.author_id).is_some_and(|current| !vote.wins_over(current)) {
            return false;
        }
        event_votes.insert(vote.author_id.clone(), vote);
        true
    }

    pub fn upsert_profile(&mut self, profile: ProfileRecord) -> bool {
        if self.profiles.get(&profile.author_id)
            .is_some_and(|current| !profile.wins_over(current)) {
            return false;
        }
        self.profiles.insert(profile.author_id.clone(), profile);
        true
    }

    /// Calcula el score de un convoy
    pub fn compute_score(&self, convoy_id: &str) -> i32 {
        self.votes
            .get(convoy_id)
            .map(|votes| votes.values().map(|v| v.data.value).sum())
            .unwrap_or(0)
    }

    /// Calcula conteo de votos (upvotes, downvotes) de un convoy
    pub fn compute_vote_counts(&self, convoy_id: &str) -> (i32, i32) {
        self.votes
            .get(convoy_id)
            .map(|votes| {
                let up = votes.values().filter(|v| v.data.value == 1).count() as i32;
                let down = votes.values().filter(|v| v.data.value == -1).count() as i32;
                (up, down)
            })
            .unwrap_or((0, 0))
    }

    /// Lista convoys vigentes (no expirados, no borrados)
    pub fn list_convoys(&self, from_date: Option<i64>, to_date: Option<i64>) -> Vec<&EventDocument> {
        let now = chrono::Utc::now().timestamp();
        let mut convoys: Vec<_> = self
            .convoys
            .values()
            .filter(|c| {
                !c.deleted
                    && c.is_retained(now)
                    && from_date.map_or(true, |from| c.event.schedule.meeting_timestamp >= from)
                    && to_date.map_or(true, |to| c.event.schedule.meeting_timestamp <= to)
            })
            .collect();

        // Ordenar por meeting_timestamp
        convoys.sort_by_key(|c| c.event.schedule.meeting_timestamp);
        convoys
    }

    /// Purge convoys expirados
    pub fn purge_expired(&mut self) {
        let now = chrono::Utc::now().timestamp();
        self.convoys.retain(|_, c| {
            if c.deleted {
                // Keep deleted convoys 7 days for tombstone propagation.
                let published_at = if c.published_at > 0 {
                    c.published_at
                } else {
                    parse_rfc3339_epoch_seconds(&c.created_at).unwrap_or(c.event.schedule.meeting_timestamp)
                };
                published_at + 7 * 86400 > now
            } else {
                c.is_retained(now)
            }
        });
        self.votes.retain(|id, _| self.convoys.contains_key(id));
    }
}

/// Estado local de canales
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct ChannelStore {
    pub channels: HashMap<String, ChannelRecord>,
}

impl ChannelStore {
    /// Carga el store desde disco
    pub fn load(data_dir: &Path) -> Result<Self> {
        let store_path = data_dir.join("channel_store.json");
        if store_path.exists() {
            let store_str = std::fs::read_to_string(&store_path)
                .context("Failed to read channel store")?;
            let store: Self = match serde_json::from_str(&store_str) {
                Ok(store) => store,
                Err(err) => {
                    eprintln!("[P2P] Failed to parse channel store: {}", err);
                    quarantine_corrupt_file(&store_path, "channel_store");
                    return Ok(Self::default());
                }
            };
            Ok(store)
        } else {
            Ok(Self::default())
        }
    }

    /// Guarda el store a disco (write atómico: temp file + rename)
    pub fn save(&self, data_dir: &Path) -> Result<()> {
        let store_path = data_dir.join("channel_store.json");
        let tmp_path = data_dir.join("channel_store.json.tmp");
        std::fs::write(&tmp_path, serde_json::to_string(self)?)
            .context("Failed to write channel store")?;
        replace_file(&tmp_path, &store_path).context("Failed to rename channel store")?;
        Ok(())
    }

    /// Crea los canales del sistema (si no existen)
    pub fn ensure_system_channels(&mut self) {
        for &name in SYSTEM_CHANNELS {
            if !self.channels.contains_key(name) {
                self.channels.insert(name.to_string(), ChannelRecord {
                    schema: SCHEMA_CHANNEL.to_string(),
                    name: name.to_string(),
                    display_name: name.to_string(),
                    creator_peer_id: SYSTEM_PEER_ID.to_string(),
                    authorized_peer_ids: Vec::new(),
                    created_at: chrono::Utc::now().timestamp(),
                    signature: String::new(),
                });
            }
        }
    }

    /// Activa un canal Patreon con key firmada
    /// Key format: base64(channel_name|peer_id|signature)
    pub fn activate_channel(
        &mut self,
        entitlement_token: &str,
        owner_peer_id: &str,
        display_name_override: Option<String>,
    ) -> Result<String, String> {
        let payload = verify_entitlement_token(entitlement_token).map_err(|e| e.to_string())?;
        if payload.owner_author_id != owner_peer_id {
            return Err("This entitlement is not for the current owner".to_string());
        }

        let normalized = payload.channel_id.trim().to_lowercase();
        if normalized.is_empty() {
            return Err("Channel id cannot be empty".to_string());
        }
        if self.channels.contains_key(&normalized) {
            return Err("Channel already exists".to_string());
        }

        let display = display_name_override
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
            .unwrap_or_else(|| {
                let trimmed = payload.display_name.trim();
                if trimmed.is_empty() { normalized.clone() } else { trimmed.to_string() }
            });

        self.channels.insert(normalized.clone(), ChannelRecord {
            schema: SCHEMA_CHANNEL.to_string(),
            name: normalized.clone(),
            display_name: display,
            creator_peer_id: owner_peer_id.to_string(),
            authorized_peer_ids: vec![owner_peer_id.to_string()],
            created_at: chrono::Utc::now().timestamp(),
            signature: String::new(),
        });

        Ok(normalized)
    }

    /// Agrega un colaborador autorizado a un canal
    pub fn grant_channel_access(
        &mut self,
        channel_name: &str,
        peer_id: &str,
        grantee_peer_id: String,
    ) -> Result<(), String> {
        let normalized = channel_name.trim().to_lowercase();
        let channel = self.channels.get_mut(&normalized)
            .ok_or("Channel not found".to_string())?;

        if !channel.is_owner(peer_id) {
            return Err("Not the channel owner".to_string());
        }

        channel.add_authorized_peer(grantee_peer_id);
        Ok(())
    }

    /// Revoca el acceso de un colaborador
    pub fn revoke_channel_access(
        &mut self,
        channel_name: &str,
        peer_id: &str,
        grantee_peer_id: &str,
    ) -> Result<(), String> {
        let normalized = channel_name.trim().to_lowercase();
        let channel = self.channels.get_mut(&normalized)
            .ok_or("Channel not found".to_string())?;

        if !channel.is_owner(peer_id) {
            return Err("Not the channel owner".to_string());
        }

        channel.remove_authorized_peer(grantee_peer_id);
        Ok(())
    }

    /// Cambia el nombre visible del canal (solo owner)
    pub fn rename_channel(
        &mut self,
        channel_name: &str,
        peer_id: &str,
        display_name: String,
    ) -> Result<(), String> {
        let normalized = channel_name.trim().to_lowercase();
        let channel = self.channels.get_mut(&normalized)
            .ok_or("Channel not found".to_string())?;
        if !channel.is_owner(peer_id) {
            return Err("Not the channel owner".to_string());
        }
        let trimmed = display_name.trim();
        if trimmed.is_empty() {
            return Err("Display name cannot be empty".to_string());
        }
        channel.display_name = trimmed.to_string();
        Ok(())
    }

    /// Elimina un canal (solo el owner puede, no se pueden eliminar canales del sistema)
    pub fn delete_channel(&mut self, channel_name: &str, peer_id: &str) -> Result<(), String> {
        let normalized = channel_name.trim().to_lowercase();
        let channel = self.channels.get(&normalized)
            .ok_or("Channel not found".to_string())?;

        if channel.is_system() {
            return Err("Cannot delete system channel".to_string());
        }

        if !channel.is_owner(peer_id) {
            return Err("Not the channel owner".to_string());
        }

        self.channels.remove(&normalized);
        Ok(())
    }

    /// Verifica si un peer específico puede publicar en el canal.
    pub fn can_peer_publish(&self, channel_name: &str, peer_id: &str) -> bool {
        let normalized = channel_name.trim().to_lowercase();
        match self.channels.get(&normalized) {
            None => false,
            Some(ch) => {
                if ch.is_system() {
                    return true;
                }
                if ch.is_owner(peer_id) || ch.is_authorized(peer_id) {
                    return true;
                }
                false
            }
        }
    }

    /// Obtiene un canal por nombre
    pub fn get_channel(&self, name: &str) -> Option<&ChannelRecord> {
        let normalized = name.trim().to_lowercase();
        self.channels.get(&normalized)
    }

    /// Elimina canales con created_at mayor a 180 días
    pub fn purge_expired(&mut self) {
        let cutoff = chrono::Utc::now().timestamp() - 180 * 86400;
        self.channels.retain(|_, ch| ch.created_at > cutoff);
    }
}

/// Registro de lista negra pública (propagado por gossip)
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BlacklistRecord {
    pub schema: String,
    pub author_peer_id: String,
    pub blocked: Vec<String>,
    pub updated_at: i64,
    /// Firma ed25519 del payload canónico
    #[serde(default)]
    pub signature: String,
}

impl BlacklistRecord {
    /// Serialización canónica para firma (sin el campo signature)
    pub fn canonical_json(&self) -> Result<String> {
        let mut copy = self.clone();
        copy.signature = String::new();
        let value = serde_json::to_value(&copy)
            .context("Failed to serialize BlacklistRecord for canonical JSON")?;
        Ok(canonical_json(&value))
    }

    /// Firma el registro con la clave secreta
    pub fn sign(&mut self, secret_key: &SecretKey) -> Result<()> {
        use ed25519_dalek::{Signer, SigningKey};

        let canonical = self.canonical_json()?;
        let message = canonical.as_bytes();

        let key_bytes = secret_key.to_bytes();
        let signing_key = SigningKey::from_bytes(&key_bytes);
        let signature = signing_key.sign(message);
        self.signature = base64::Engine::encode(
            &base64::engine::general_purpose::STANDARD,
            signature.to_bytes(),
        );

        Ok(())
    }

    /// Verifica la firma del registro
    pub fn verify(&self) -> Result<bool> {
        use ed25519_dalek::{Verifier, VerifyingKey};

        if self.signature.is_empty() {
            return Ok(false);
        }

        let key_array = decode_peer_id_bytes(&self.author_peer_id)?;
        let verifying_key = VerifyingKey::from_bytes(&key_array)?;

        let sig_bytes = base64::Engine::decode(
            &base64::engine::general_purpose::STANDARD,
            &self.signature,
        )?;
        if sig_bytes.len() != 64 {
            return Ok(false);
        }

        let mut sig_array = [0u8; 64];
        sig_array.copy_from_slice(&sig_bytes);
        let sig = ed25519_dalek::Signature::from_bytes(&sig_array);

        let canonical = self.canonical_json()?;
        Ok(verifying_key.verify(canonical.as_bytes(), &sig).is_ok())
    }
}

/// Estado local de blacklists públicas recibidas por gossip
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct BlacklistStore {
    pub blacklists: HashMap<String, BlacklistRecord>,
}

impl BlacklistStore {
    pub fn load(data_dir: &Path) -> Result<Self> {
        let store_path = data_dir.join("blacklist_store.json");
        if store_path.exists() {
            let s = std::fs::read_to_string(&store_path)
                .context("Failed to read blacklist store")?;
            let store: Self = match serde_json::from_str(&s) {
                Ok(store) => store,
                Err(err) => {
                    eprintln!("[P2P] Failed to parse blacklist store: {}", err);
                    quarantine_corrupt_file(&store_path, "blacklist_store");
                    return Ok(Self::default());
                }
            };
            Ok(store)
        } else {
            Ok(Self::default())
        }
    }

    pub fn save(&self, data_dir: &Path) -> Result<()> {
        let store_path = data_dir.join("blacklist_store.json");
        let tmp_path = data_dir.join("blacklist_store.json.tmp");
        std::fs::write(&tmp_path, serde_json::to_string(self)?)
            .context("Failed to write blacklist store")?;
        replace_file(&tmp_path, &store_path).context("Failed to rename blacklist store")?;
        Ok(())
    }

    pub fn upsert(&mut self, record: BlacklistRecord) {
        self.blacklists.insert(record.author_peer_id.clone(), record);
    }

    /// Elimina blacklists con updated_at mayor a 90 días
    pub fn purge_expired(&mut self) {
        let cutoff = chrono::Utc::now().timestamp() - 90 * 86400;
        self.blacklists.retain(|_, r| r.updated_at > cutoff);
    }
}

