/// Almacén de nicks conocidos (peer_id → nick/alias)
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct KnownNicksStore {
    /// peer_id → nick conocido (del gossip)
    #[serde(default)]
    pub nicks: HashMap<String, String>,
    /// peer_id → alias local (definido por el usuario)
    #[serde(default)]
    pub aliases: HashMap<String, String>,
}

impl KnownNicksStore {
    /// Carga el store desde disco
    pub fn load(data_dir: &Path) -> Self {
        let path = data_dir.join("known_nicks.json");
        std::fs::read_to_string(&path)
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_default()
    }

    /// Guarda el store a disco (atómico: temp + rename)
    pub fn save(&self, data_dir: &Path) -> Result<()> {
        let path = data_dir.join("known_nicks.json");
        let tmp_path = data_dir.join("known_nicks.json.tmp");
        if let Ok(json) = serde_json::to_string_pretty(self) {
            std::fs::write(&tmp_path, json)
                .context("Failed to write known nicks temp file")?;
            replace_file(&tmp_path, &path).context("Failed to rename known nicks")?;
        }
        Ok(())
    }

    /// Obtiene el nombre a mostrar para un peer_id (prioridad: alias > nick > peer_id truncado)
    pub fn display_name(&self, peer_id: &str) -> String {
        if let Some(alias) = self.aliases.get(peer_id) {
            return alias.clone();
        }
        if let Some(nick) = self.nicks.get(peer_id) {
            return nick.clone();
        }
        // Peer ID truncado como fallback
        if peer_id.len() > 12 {
            format!("{}…{}", &peer_id[..6], &peer_id[peer_id.len()-4..])
        } else {
            peer_id.to_string()
        }
    }

    /// Actualiza el nick conocido de un peer_id (desde gossip)
    pub fn update_nick(&mut self, peer_id: String, nick: String) {
        if !nick.trim().is_empty() && nick.len() <= 64 {
            self.nicks.insert(peer_id, nick);
        }
    }

    /// Define un alias local para un peer_id
    pub fn set_alias(&mut self, peer_id: String, alias: String) {
        if alias.trim().is_empty() {
            self.aliases.remove(&peer_id);
        } else {
            self.aliases.insert(peer_id, alias);
        }
    }
}

/// Decodifica un peer_id (hex o base64) a 32 bytes.
/// iroh usa formato hex (64 chars), pero algunos formatos usan base64.
pub fn decode_peer_id_bytes(peer_id: &str) -> Result<[u8; 32]> {
    fn decode_base64_peer_id(peer_id: &str) -> Result<Vec<u8>> {
        base64::Engine::decode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, peer_id)
            .or_else(|_| base64::Engine::decode(&base64::engine::general_purpose::STANDARD, peer_id))
            .context("Failed to decode base64 peer_id")
    }

    if let Some(encoded) = peer_id.strip_prefix("ed25519:") {
        let bytes = decode_base64_peer_id(encoded).context("Failed to decode CTES author_id")?;
        return bytes.try_into().map_err(|_| anyhow::anyhow!("Invalid CTES author_id length"));
    }
    // Hex format: 64 hex chars = 32 bytes (iroh default)
    if peer_id.len() == 64 && peer_id.chars().all(|c| c.is_ascii_hexdigit()) {
        let bytes = hex::decode(peer_id).context("Failed to decode hex peer_id")?;
        if bytes.len() != 32 {
            anyhow::bail!("Invalid peer_id length: expected 32, got {}", bytes.len());
        }
        let mut key_array = [0u8; 32];
        key_array.copy_from_slice(&bytes);
        return Ok(key_array);
    }
    // Base64 format: fallback
    let bytes = decode_base64_peer_id(peer_id)?;
    if bytes.len() != 32 {
        anyhow::bail!("Invalid peer_id length: expected 32, got {}", bytes.len());
    }
    let mut key_array = [0u8; 32];
    key_array.copy_from_slice(&bytes);
    Ok(key_array)
}

pub fn otes_author_id(peer_id: &str) -> Result<String> {
    let bytes = decode_peer_id_bytes(peer_id)?;
    Ok(format!(
        "ed25519:{}",
        base64::Engine::encode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, bytes)
    ))
}

/// Serialización canónica JSON (claves ordenadas recursivamente)
fn canonical_json(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => "null".to_string(),
        serde_json::Value::Bool(b) => b.to_string(),
        serde_json::Value::Number(n) => n.to_string(),
        serde_json::Value::String(s) => serde_json::to_string(s).unwrap_or_else(|_| "\"\"".to_string()),
        serde_json::Value::Array(arr) => {
            let items: Vec<String> = arr.iter().map(canonical_json).collect();
            format!("[{}]", items.join(","))
        }
        serde_json::Value::Object(obj) => {
            let mut keys: Vec<_> = obj.keys().collect();
            keys.sort();
            let items: Vec<String> = keys
                .iter()
                .map(|k| format!("{}:{}", serde_json::to_string(k).unwrap_or_else(|_| "\"\"".to_string()), canonical_json(&obj[*k])))
                .collect();
            format!("{{{}}}", items.join(","))
        }
    }
}
